"""SA08 middle packages: explicit close-reading judgments, not heading inference.
All statements below were authored after continuous reading of the two supplied
transcriptions and notes. Extraction only supplies exact source excerpts/locators.
Run output is retained in logs/middle_build.log. Parent merges these provisional IDs.
"""
from pathlib import Path
import json,csv,datetime
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'work/middle';OUT.mkdir(exist_ok=True)
P='MPL_136_095-141';Q='MPL_136_189-234'
texts={p:(ROOT/'sources/texts/pro'/f'{p}_transcription.tex').read_text().splitlines() for p in(P,Q)}
source_entries={e['entry_id']:e for p in(P,Q) for e in json.loads((OUT/f'{p}_entries_source.json').read_text())}
items=[];claims=[];problems=[];readings=[];links=[];events=[];entries=[]
DATE='2026-11-19';WHO='GPT-6 Astra Pro; effort not exposed by runtime; SA08/middle'
def source(p,nums):return [f'{p}#{n}' for n in nums]
def excerpt(p,line):
 a,b=map(int,line.split('-')) if '-' in line else (int(line),int(line))
 s=' '.join(x.strip() for x in texts[p][a-1:b] if x.strip() and not x.startswith(('\\scanpage','\\margin','\\begin{center}')))
 return s[:420]+(' …' if len(s)>420 else '')
def I(n,p,nums,kind,scans,line,title,statement,reconstruction='',check='agrees',reason=''):
 it={'id':f'SA08-{n}','sources':source(p,nums),'kind':kind,'cote':'136','scans':scans,'lines':f'{p}_transcription.tex:{line}','his_words':excerpt(p,line),'statement':statement,'reconstruction':reconstruction or 'No text supplied beyond the literal passage is attributed to the author.','check':check,'check_reason':reason or 'Compared the indexed note with the cited live passage and its local cancellations.','title':title,'package':p}
 items.append(it);return it
def EV(id,typ,outcome):events.append({'statement_id':id,'date':DATE,'who':WHO,'type':typ,'outcome':outcome})
def C(n,itemnums,p,scans,line,statement,status,cls,fate,refs,computation='',confidence='high',search=''):
 claims.append({'id':f'SA08-C{n}','items':[f'SA08-{i}' for i in itemnums],'cote':'136','scans':scans,'lines':f'{p}_transcription.tex:{line}','his_statement':excerpt(p,line),'statement':statement,'status_on_pages':status,'computation':computation or 'No numerical computation is used; see the hypothesis-by-hypothesis source comparison and manuscript reading.','class':cls,'fate':fate,'fate_date':'As of 2026-11-19; first circulation and publication distinguished in cited reference records.','present_status':fate,'refs':refs,'confidence':confidence,'search_record':search,'attribution':'Grothendieck manuscript' if n not in(129,187) else ('Unattributed English donor sheet' if n==129 else 'M. Stoia, explicitly attributed donor typescript')})
def V(p,n,item,verdict,reason):entries.append({'entry_id':f'{p}#{n}','item_id':f'SA08-{item}','verdict':verdict,'reason':reason})

